1	/**
2	 * Per-user rate limiting: 100 reads and 20 writes per minute.
3	 *
4	 * Fixed windows keyed by user and kind. A window is opened on the first request and counts
5	 * requests until it expires.
6	 */
7	const LIMITS: Record<'read' | 'write', number> = { read: 100, write: 20 };
8	const WINDOW_MS = 60_000;
9	
10	interface Window {
11	  openedAt: number;
12	  count: number;
13	}
14	
15	const windows = new Map<string, Window>();
16	
17	export function checkRateLimit(userId: string, kind: 'read' | 'write', now = Date.now()): boolean {
18	  const key = `${userId}:${kind}`;
19	  const current = windows.get(key);
20	  if (!current) {
21	    windows.set(key, { openedAt: now, count: 1 });
22	    return true;
23	  }
24	  if (now - current.openedAt > WINDOW_MS) {
25	    current.count = 0;
26	  }
27	  current.count += 1;
28	  return current.count <= LIMITS[kind];
29	}
30	
31	export function resetRateLimits(): void {
32	  windows.clear();
33	}
