import { type Request, type Response, type NextFunction } from 'express';
import { verifyJwt, type JwtClaims } from '../lib/jwt.ts';

/** A request that has passed through `requireAuth`, so its claims are known. */
export type AuthedRequest = Request & { user: JwtClaims };

/** The same request before `requireAuth` has run, when the claims are not yet attached. */
type MaybeAuthedRequest = Request & { user?: JwtClaims };

/**
 * Verifies the bearer token on the request and attaches its claims as `req.user`.
 *
 * Responds 401 with a generic message when the header is missing, or with the verification
 * failure itself (malformed token, invalid signature, expired) when the token does not verify.
 */
export function requireAuth(req: MaybeAuthedRequest, res: Response, next: NextFunction) {
  const token = req.headers.authorization?.replace(/^Bearer /, '');
  if (!token) return res.status(401).json({ error: 'Unauthorized' });
  try {
    req.user = verifyJwt(token);
  } catch (error) {
    return res.status(401).json({ error: (error as Error).message });
  }
  return next();
}

import { Router, type Request, type Response, type NextFunction } from 'express';
import { signJwt } from './lib/jwt.ts';
import { requireAuth, type AuthedRequest } from './middleware/auth.ts';
import { checkRateLimit } from './rate-limit.ts';
import { findUserByEmail, listInvoices, listSubscriptions } from './store.ts';

export const router = Router();

router.post('/login', (req: Request, res: Response) => {
  const { email, password } = req.body as { email?: string; password?: string };
  const user = email ? findUserByEmail(email) : undefined;
  if (!user || user.password !== password) {
    return res.status(401).json({ error: 'Invalid email or password' });
  }
  return res.json({ token: signJwt({ sub: user.id, role: user.role }) });
});

router.get('/me', requireAuth, (req: AuthedRequest, res: Response) => {
  return res.json({ id: req.user.sub, role: req.user.role });
});

router.get('/subscriptions', requireAuth, (req: AuthedRequest, res: Response) => {
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listSubscriptions(req.user.sub));
});

router.get('/invoices', requireAuth, (req: AuthedRequest, res: Response) => {
  if (!checkRateLimit(req.user.sub, 'read')) return res.status(429).json({ error: 'Too many requests' });
  return res.json(listInvoices(req.user.sub));
});

router.post('/subscriptions/:id/cancel', requireAuth, (req: AuthedRequest, res: Response, next: NextFunction) => {
  if (!checkRateLimit(req.user.sub, 'write')) return res.status(429).json({ error: 'Too many requests' });
  const subscription = listSubscriptions(req.user.sub).find((entry) => entry.id === req.params.id);
  if (!subscription) return next();
  subscription.status = 'cancelled';
  return res.json(subscription);
});

